def _condition(x):
    if isinstance(x, dict):
        return {k: _condition(v) for (k, v) in x.items()}
    if isinstance(x, list):
        return [_condition(v) for v in x]
    return x * 1000 if isinstance(x, float) else x
for _k in ['features', 'profile', 'center_xy']:
    if _k in PARAMETERS:
        PARAMETERS[_k] = _condition(PARAMETERS[_k])
PARAMETERS['construction_scale'] = 1000
